<script setup lang="ts">
import { protocolWords, chalkboardPositions, shatteredCipher, reckoningElement, samFiles, reckoningFiles } from '~/utils/bo6Dlc.mjs'
const props = defineProps<{tool:string}>()
const {state,change,undo,reset,canUndo,saveError} = usePuzzleState(props.tool)
const fieldId = useId()
const confirmReset = ref(false)
const result = computed(() => props.tool === 'bo6-shattered-cipher' ? shatteredCipher(state.value) : props.tool === 'bo6-reckoning-element' ? reckoningElement(state.value) : reckoningFiles(state.value))
function update(key:string,value:any) { change({...state.value,[key]:value}) }
</script>
<template>
  <div class="dlc-tool">
    <template v-if="tool==='bo6-shattered-cipher'">
      <p>Read the fax in East Foyer, then copy the <strong>entire letter cluster</strong> containing each needed letter from the Nursery chalkboard. The other clusters can stay blank. Spaces are ignored.</p>
      <div class="choices" role="group" aria-label="Protocol on fax"><button v-for="word in protocolWords" :key="word" :aria-pressed="state.word===word" @click="update('word',word)">{{word}}</button></div>
      <GuideIllustrations :images="[{src:'/images/bo6-shattered-veil/shattered-veil-chalkboard.webp',alt:'Nursery chalkboard example: copy the clusters from your own match, not this example'}]" />
      <p class="muted">The reference photo shows the layout. Its letters may differ from your match. Count the requested letter too.</p>
      <div class="cluster-grid"><label v-for="(position,i) in chalkboardPositions" :key="position" :for="`${fieldId}-group-${i}`">{{position}}<input :id="`${fieldId}-group-${i}`" :value="state[`group-${i}`]" maxlength="20" autocapitalize="characters" autocomplete="off" spellcheck="false" :placeholder="i===0?'e.g. E':''" @input="update(`group-${i}`,($event.target as HTMLInputElement).value.toUpperCase())" /></label></div>
      <ol v-if="result.letters" class="decode"><li v-for="(row,i) in result.letters" :key="i"><strong>{{row.letter}}</strong><span>{{row.group||'Not found yet'}}</span><b>{{row.digit??'—'}}</b><small>{{row.index>=0?chalkboardPositions[row.index]:'Copy its cluster'}}</small></li></ol>
    </template>
    <template v-else-if="tool==='bo6-reckoning-element'">
      <p>Read both flashing monitors <strong>during the same round</strong>. Take the Deadshot monitor’s initial first, then the family-tank monitor’s initial if it displays a word.</p>
      <div class="choices" role="group" aria-label="Number of active word monitors"><button v-for="count in ['One word','Two words']" :key="count" :aria-pressed="state.screens===count" @click="update('screens',count)">{{count}}</button></div>
      <div class="monitor-grid"><section><GuideIllustrations :images="[{src:'/images/bo6-reckoning/reckoning-second-static-screen.webp',alt:'First initial: monitor beside Deadshot Daiquiri'}]" /><label :for="`${fieldId}-first`">1. Deadshot monitor: word or initial<input :id="`${fieldId}-first`" :value="state.first" maxlength="30" autocomplete="off" spellcheck="false" @input="update('first',($event.target as HTMLInputElement).value)" /></label></section><section v-if="state.screens!=='One word'"><GuideIllustrations :images="[{src:'/images/bo6-reckoning/reckoning-first-static-screen.webp',alt:'Second initial: monitor behind the family tank'}]" /><label :for="`${fieldId}-second`">2. Family-tank monitor: word or initial<input :id="`${fieldId}-second`" :value="state.second" maxlength="30" autocomplete="off" spellcheck="false" @input="update('second',($event.target as HTMLInputElement).value)" /></label></section></div>
      <p v-if="result.symbol" class="element"><strong>{{result.symbol}}</strong><span v-if="result.number">Atomic number {{result.number}}</span></p>
      <details><summary>See the in-game periodic table</summary><GuideIllustrations :images="[{src:'/images/bo6-reckoning/periodic-table.jpeg',alt:'Reckoning laboratory periodic table; use the atomic number at the top of each element cell'}]" /></details>
    </template>
    <template v-else>
      <p>Select the <strong>four belongings shown in your S.A.M. files</strong>. Each photo shows a search location. The helper orders the printed dates and keeps their file numbers attached.</p>
      <div class="file-grid"><button v-for="file in samFiles" :key="file.id" class="file-choice" :aria-pressed="!!state[file.id]" @click="update(file.id,!state[file.id])"><img :src="file.image" :alt="`${file.name}: ${file.location}`" loading="lazy" width="1920" height="1080" /><span><strong>{{file.name}}</strong><small>File {{file.digit}} · {{file.displayDate}}</small><small>{{state[file.id]?'Selected':'Select this file'}}</small></span></button></div>
      <ol v-if="result.selected?.length" class="file-order"><li v-for="file in result.selected" :key="file.id"><span>{{file.displayDate}}</span><strong>{{file.name}}</strong><b>{{file.digit}}</b></li></ol>
      <details v-if="result.selected?.length"><summary>Enlarge selected document references</summary><GuideIllustrations :images="result.selected.map((file:any)=>({src:file.image,alt:`${file.name}: file ${file.digit}, archived ${file.displayDate}`}))" /></details>
      <p class="muted">Only four of the six appear. Read the document itself; finding an empty table does not select its usual file. U.S. dates on the documents use month/day/year.</p>
    </template>
    <div class="result" :class="result.status" role="status" aria-live="polite"><strong v-if="result.code" class="code">{{result.code}}</strong><p>{{result.message}}</p></div>
    <div class="actions"><button :disabled="!canUndo" @click="undo">Undo last change</button><button @click="confirmReset=!confirmReset">Reset helper</button></div>
    <div v-if="confirmReset" class="reset"><p>Clear this helper’s saved observations?</p><div class="actions"><button @click="reset();confirmReset=false">Clear observations</button><button @click="confirmReset=false">Keep observations</button></div></div>
    <p v-if="saveError" role="alert">These observations could not be saved. Keep this page open.</p>
    <p class="muted">Saved on this device; shared with the full-page helper. Screenshots: COD Zombies Guides and r/CODZombies, linked in the map guide.</p>
  </div>
</template>
<style scoped>
.dlc-tool{color:var(--text);line-height:1.6;min-width:0}.dlc-tool p{margin:.8rem 0}.dlc-tool button,.dlc-tool input{font:inherit}.dlc-tool button{min-height:44px;padding:.55rem .8rem;border:1px solid var(--line);border-radius:7px;background:var(--surface-2);color:var(--text);cursor:pointer}.dlc-tool button:hover:not(:disabled),.dlc-tool button[aria-pressed=true]{border-color:var(--gold);background:var(--gold-dim)}.dlc-tool button:disabled{opacity:.45;cursor:default}.dlc-tool :focus-visible{outline:2px solid var(--gold);outline-offset:3px}.dlc-tool input{display:block;width:100%;min-height:44px;margin-top:.4rem;padding:.5rem .7rem;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:6px;caret-color:var(--gold)}.dlc-tool label{font-size:.82rem}.choices,.actions{display:flex;gap:.5rem;flex-wrap:wrap;margin:1rem 0}.cluster-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.8rem}.cluster-grid input{text-transform:uppercase;font-family:monospace}.decode{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.6rem;list-style:none;margin:1rem 0;padding:0}.decode li{display:flex;flex-direction:column;padding:.7rem;border:1px solid var(--line);border-radius:7px;overflow-wrap:anywhere}.decode strong,.decode b{font-size:1.4rem;color:var(--gold)}.decode span{font-family:monospace;font-size:.8rem}.decode small,.muted{color:var(--muted);font-size:.78rem}.result{border:1px solid var(--line);background:var(--surface-2);border-radius:8px;padding:1rem;margin:1rem 0}.result.invalid{border-color:#c8815c}.result p{margin:.3rem 0}.code{display:block;font-size:2.2rem;letter-spacing:.15em;font-family:monospace;color:var(--gold);font-variant-numeric:tabular-nums}.monitor-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:1rem}.monitor-grid :deep(.guide-illustrations){display:block}.monitor-grid section{min-width:0}.element{display:flex;align-items:center;gap:1rem}.element strong{font-size:2rem;color:var(--gold)}summary{cursor:pointer;min-height:44px;padding:.6rem 0;color:var(--gold)}.file-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,180px),1fr));gap:.7rem}.file-grid .file-choice{padding:0;text-align:left;overflow:hidden}.file-choice img{width:100%;height:auto;aspect-ratio:16/9;object-fit:cover}.file-choice span{display:flex;flex-direction:column;gap:.2rem;padding:.65rem}.file-choice small{font-size:.72rem;color:var(--muted)}.file-order{padding-left:1.5rem}.file-order li{padding:.45rem 0}.file-order li>*{margin-right:.7rem}.file-order span{font-size:.76rem;color:var(--muted)}.file-order b{color:var(--gold)}.reset{padding:.5rem 0}.dlc-tool ::selection{background:var(--gold-dim)}@media(max-width:440px){.decode{grid-template-columns:repeat(2,minmax(0,1fr))}.cluster-grid{gap:.5rem}.cluster-grid label{font-size:.72rem}.cluster-grid input{padding:.45rem;font-size:.85rem}}
</style>
